/* 固定高度的編排與參數工作區。只產生明確標示的離線模擬結果。 */
window.FlowDemo=(()=>{
  let draft=null,selected='verify',dirty=false,collapsed=false,zoom=1,raw={},picked=null,busy=false,stop=false,last=null,storageVersion=0,message='';
  const C=v=>JSON.parse(JSON.stringify(v)),E=v=>esc(String(v)),q=s=>document.querySelector(s);
  const initial=()=>({version:2,parameterBindingVersion:1,name:'建立與驗證紀錄',nodes:[{id:'create',sceneId:'BA-001',repeat:2,x:40,y:60,bindings:{}},{id:'verify',sceneId:'BA-002',repeat:1,x:340,y:60,bindings:{expectedTitle:{kind:'output',source:'create',field:'title'}}}],edges:[{source:'create',target:'verify'}]});
  const catalog=()=>Object.fromEntries(state.scenes.map(s=>[s.id,C(s)]));
  const current=()=>draft.nodes.find(n=>n.id===selected)||draft.nodes[0];
  function init(){if(!draft){draft=C(state.workflow||initial());storageVersion=state.workflowRevision||0}}
  function changed(){dirty=true;message='尚未儲存';status()}
  function status(error=false){const e=q('#wf-save-state');if(e){e.textContent=message|| (dirty?'尚未儲存':'已儲存');e.classList.toggle('wf-error',error)}}
  function html(){init();return `<div class="wf-toolbar"><strong>自由試驗場</strong><small>離線模擬 · 參數契約 v1</small><button class="button" id="wf-save">儲存工作流</button><button class="button" id="wf-export">匯出 JSON</button><button class="button primary" id="wf-run">檢查並模擬執行</button><button class="button" id="wf-stop" disabled>停止</button></div><div class="wf-layout"><section class="panel wf-library"><h2>場景庫</h2>${state.scenes.filter(s=>s.state==='已發布').map(s=>`<button class="library-item" data-add="${E(s.id)}"><strong>${E(s.id)}</strong><span>${E(s.name)}</span><small>＋ 加入畫布</small></button>`).join('')}</section><div class="wf-center"><section class="panel wf-canvas-panel"><div class="wf-canvas-tools"><span>依賴畫布 · 拖動節點，點擊連線設定參數</span><button class="button" id="wf-minus" aria-label="縮小畫布">−</button><span id="wf-scale">100%</span><button class="button" id="wf-plus" aria-label="放大畫布">＋</button><button class="button" id="wf-fit">適應</button></div><div class="wf-viewport"><div class="wf-spacer"><div class="wf-stage" id="wf-stage"></div></div></div></section><section class="panel wf-parameters" id="wf-parameters"></section></div><section class="panel wf-config" id="wf-config"></section></div><div class="panel wf-summary" id="wf-result"></div><p class="wf-hint">先全圖驗參，再依序執行。下游使用上游最後一次成功的實際出參；失敗立即停止。<a href="#increments">查看增量規則與介面指引</a></p>`}
  function graph(){
    const box=q('#wf-stage');if(!box)return;
    box.innerHTML=`<svg width="800" height="400" aria-label="節點依賴連線"><defs><marker id="wf-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#147fe6"/></marker></defs>${draft.edges.map((e,i)=>`<path class="wf-edge" data-edge-line="${i}" marker-end="url(#wf-arrow)"/><path class="wf-hit" data-edge="${i}" tabindex="0" role="button" aria-label="${E(e.source)} 到 ${E(e.target)} 的參數設定"/>`).join('')}</svg>${draft.nodes.map(n=>`<div class="wf-node ${n.id===selected?'selected':''}" data-node="${E(n.id)}" tabindex="0" role="button" aria-label="選取節點 ${E(n.id)}" style="left:${Number(n.x)||0}px;top:${Number(n.y)||0}px"><span class="tag">${E(n.sceneId)}</span> <small>${E(n.id)} · ×${n.repeat}</small><strong title="${E(getScene(n.sceneId)?.name||n.sceneId)}">${E(getScene(n.sceneId)?.name||n.sceneId)}</strong><small>入參 → 自動化 → 斷言 → 出參</small><button class="wf-port in" data-in="${E(n.id)}" title="選取下游" aria-label="連接至 ${E(n.id)}"></button><button class="wf-port out" data-out="${E(n.id)}" title="選取上游，再點下游" aria-label="從 ${E(n.id)} 連出"></button></div>`).join('')}`;
    box.querySelectorAll('[data-node]').forEach(el=>{
      el.onkeydown=e=>{if(e.target===el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();select(el.dataset.node)}};
      el.onpointerdown=e=>{if(e.target.closest('button')||busy)return;select(el.dataset.node,false);const n=current(),sx=e.clientX,sy=e.clientY,x=n.x,y=n.y;let moved=false;el.setPointerCapture(e.pointerId);el.onpointermove=ev=>{if(Math.abs(ev.clientX-sx)+Math.abs(ev.clientY-sy)>3)moved=true;if(!moved)return;n.x=Math.max(12,Math.min(570,x+(ev.clientX-sx)/zoom));n.y=Math.max(12,Math.min(290,y+(ev.clientY-sy)/zoom));el.style.left=n.x+'px';el.style.top=n.y+'px';edges()};el.onpointerup=()=>{el.onpointermove=null;el.onpointerup=null;if(moved)changed()}}
    });
    box.querySelectorAll('[data-edge]').forEach(el=>{const fn=()=>{const e=draft.edges[Number(el.dataset.edge)];select(e.target);collapsed=false;parameters()};el.onclick=fn;el.onkeydown=e=>{if(e.key==='Enter')fn()}});
    box.querySelectorAll('[data-out]').forEach(el=>el.onclick=()=>{picked={node:el.dataset.out};toast('已選上游；點擊另一節點的入參圓點')});
    box.querySelectorAll('[data-in]').forEach(el=>el.onclick=()=>{if(picked?.node&&!picked.field){connect(picked.node,el.dataset.in);picked=null}else select(el.dataset.in)});
    scale();edges();
  }
  function edges(){const stage=q('#wf-stage');if(!stage)return;const root=stage.getBoundingClientRect();draft.edges.forEach((e,i)=>{const a=[...stage.querySelectorAll('[data-out]')].find(n=>n.dataset.out===e.source)?.getBoundingClientRect(),b=[...stage.querySelectorAll('[data-in]')].find(n=>n.dataset.in===e.target)?.getBoundingClientRect();if(!a||!b)return;const x=(a.x+a.width/2-root.x)/zoom,y=(a.y+a.height/2-root.y)/zoom,xx=(b.x+b.width/2-root.x)/zoom,yy=(b.y+b.height/2-root.y)/zoom;const d=`M${x},${y} C${x+50},${y} ${xx-50},${yy} ${xx},${yy}`;stage.querySelector(`[data-edge-line="${i}"]`)?.setAttribute('d',d);stage.querySelector(`[data-edge="${i}"]`)?.setAttribute('d',d)})}
  function scale(){const s=q('#wf-stage');if(!s)return;s.style.transform=`scale(${zoom})`;q('.wf-spacer').style.width=800*zoom+'px';q('.wf-spacer').style.height=400*zoom+'px';q('#wf-scale').textContent=Math.round(zoom*100)+'%';edges()}
  function select(id,redraw=true){selected=id;q('#wf-stage')?.querySelectorAll('[data-node]').forEach(n=>n.classList.toggle('selected',n.dataset.node===id));config();parameters();if(redraw)edges()}
  function cleanup(source,target){for(const n of draft.nodes){if(target&&n.id!==target)continue;for(const[k,b]of Object.entries(n.bindings||{}))if(b.kind==='output'&&b.source===source)delete n.bindings[k]}}
  function connect(source,target){if(busy)return;try{if(source===target)throw Error('不可連接自己');if(draft.edges.some(e=>e.source===source&&e.target===target))throw Error('連線已存在');const trial=C(draft);trial.edges.push({source,target});const walk=(id,seen=new Set())=>{if(id===source)return true;if(seen.has(id))return false;seen.add(id);return trial.edges.filter(e=>e.source===id).some(e=>walk(e.target,seen))};if(walk(target))throw Error('不可建立循環');draft=trial;selected=target;changed();graph();config();parameters()}catch(e){toast(e.message)}}
  function config(){const node=current(),box=q('#wf-config');if(!box)return;if(!node){box.innerHTML='<h2>節點設定</h2><p>先加入場景。</p>';return}selected=node.id;
    const parents=draft.edges.filter(e=>e.target===node.id),scene=getScene(node.sceneId);
    box.innerHTML=`<h2>節點設定 · ${E(node.id)}</h2><p><strong>${E(node.sceneId)}</strong> ${E(scene?.name||'未知場景')}</p><label>重複執行次數<input id="wf-repeat" type="number" min="1" max="1000" value="${node.repeat}"></label><label>加入直接上游<div class="wf-connect"><select id="wf-source">${draft.nodes.filter(n=>n.id!==node.id).map(n=>`<option value="${E(n.id)}">${E(n.id)} · ${E(n.sceneId)}</option>`).join('')}</select><button class="button" id="wf-connect">連接</button></div></label><div>${parents.map(e=>`<p>${E(e.source)} → ${E(node.id)} <button class="text-btn" data-unlink="${E(e.source)}">移除連線</button></p>`).join('')}</div><button class="button danger" id="wf-remove">移除節點</button><p>直接上游出參：可點選或拖曳到下方入參欄位。</p><div class="wf-outputs">${parents.flatMap(e=>{const n=draft.nodes.find(n=>n.id===e.source);return Object.keys(getScene(n.sceneId)?.outputSchema.properties||{}).map(k=>`<button class="wf-output" draggable="true" data-source="${E(n.id)}" data-field="${E(k)}" title="${E(n.id+'.'+k)}">${E(n.id+'.'+k)}</button>`)}).join('')||'<span class="muted">尚無上游連線</span>'}</div><label>失敗演示<select id="wf-fail"><option value="">全部通過</option>${draft.nodes.map(n=>`<option value="${E(n.id)}">${E(n.id)} 斷言失敗</option>`).join('')}</select></label>`;
    q('#wf-repeat').onchange=e=>{if(busy)return;node.repeat=Number(e.target.value);changed();graph()};
    q('#wf-connect').onclick=()=>connect(q('#wf-source').value,node.id);
    q('#wf-remove').onclick=()=>{if(busy)return;cleanup(node.id);draft.nodes=draft.nodes.filter(n=>n.id!==node.id);draft.edges=draft.edges.filter(e=>e.source!==node.id&&e.target!==node.id);delete raw[node.id];selected=draft.nodes[0]?.id;changed();graph();config();parameters()};
    box.querySelectorAll('[data-unlink]').forEach(b=>b.onclick=()=>{if(busy)return;const source=b.dataset.unlink;cleanup(source,node.id);draft.edges=draft.edges.filter(e=>e.source!==source||e.target!==node.id);changed();graph();config();parameters()});
    box.querySelectorAll('[data-source]').forEach(b=>{b.onclick=()=>{picked={node:b.dataset.source,field:b.dataset.field};toast('已選出參；點擊對應的入參名稱')};b.ondragstart=e=>{picked={node:b.dataset.source,field:b.dataset.field};e.dataTransfer.setData('text/plain',JSON.stringify(picked))}});
  }
  function bindField(name,source,field){if(busy)return;const n=current(),scene=getScene(n.sceneId),up=draft.nodes.find(x=>x.id===source);if(!up||!draft.edges.some(e=>e.source===source&&e.target===n.id)||!Parameters.compatible(getScene(up.sceneId).outputSchema.properties[field]||{},scene.inputSchema.properties[name]))return toast('來源必須為已連接的上游，且型別相容');n.bindings[name]={kind:'output',source,field};delete (raw[n.id]||{})[name];picked=null;changed();parameters()}
  function manualText(n,name,schema){if(Object.hasOwn(raw[n.id]||{},name))return raw[n.id][name];const v=n.bindings[name]?.value;return schema.type==='string'?String(v??''):v===undefined?'':JSON.stringify(v)}
  function syncRaw(){for(const n of draft.nodes){const scene=getScene(n.sceneId);for(const[name,text]of Object.entries(raw[n.id]||{})){if(n.bindings[name]?.kind!=='value')continue;const schema=scene.inputSchema.properties[name];try{n.bindings[name].value=schema.type==='string'?text:JSON.parse(text)}catch{throw Error(n.id+'.'+name+' 請輸入有效 JSON；草稿已保留')}}}}
  function parameters(){const box=q('#wf-parameters'),n=current();if(!box)return;const s=n&&getScene(n.sceneId);let planned={},error='';if(n)try{planned=Parameters.plan(n,draft,catalog())}catch(e){error=e.message}
    const modes=[['auto','同名匹配'],['default','腳本預設'],['value','人工指定'],['output','參數連線']];
    box.innerHTML=`<div class="panel-header"><h2>入參設定 ${n?'· '+E(n.id):''}</h2><button class="text-btn" id="wf-collapse">${collapsed?'展開':'收合'} · 高度固定</button></div><div class="wf-param-scroll">${collapsed?'<p class="wf-hint" style="padding:10px">設定已收合，尚未儲存的輸入仍保留。</p>':!n?'<div class="empty">先選取節點。</div>':`<table><thead><tr><th>入參 / 型別</th><th>取值方式</th><th>值或來源</th></tr></thead><tbody>${Object.entries(s.inputSchema.properties).map(([name,schema])=>{
      const b=n.bindings[name],mode=b?.kind||'auto',p=planned[name],parents=draft.edges.filter(e=>e.target===n.id),candidates=parents.flatMap(e=>{const u=draft.nodes.find(u=>u.id===e.source);return Object.entries(getScene(u.sceneId).outputSchema.properties).filter(([k,f])=>Parameters.compatible(f,schema)).map(([k])=>({source:u.id,field:k}))});
      const detail=mode==='value'?`<input data-manual="${E(name)}" aria-label="${E(name)} 人工值" value="${E(manualText(n,name,schema))}" placeholder="${schema.type==='string'?'文字':'JSON 值'}">`:mode==='output'?`<select data-binding="${E(name)}" aria-label="${E(name)} 出參來源"><option value="">選擇上游出參</option>${candidates.map(c=>`<option value="${E(c.source+'|'+c.field)}" ${b.source===c.source&&b.field===c.field?'selected':''}>${E(c.source+'.'+c.field)}</option>`).join('')}</select>`:`<span>${mode==='default'?'使用場景預設：'+E(JSON.stringify(s.defaults[name])??'未設定'):p?.kind==='output'?'自動 ← '+E(p.source+'.'+p.field):error?'待解決來源衝突':'預設 ← '+E(JSON.stringify(s.defaults[name])??'未設定')}</span>`;
      return `<tr data-field-row="${E(name)}"><td><button class="text-btn" data-input-port="${E(name)}" title="選取出參後點此連接"><i class="wf-field-port"></i>${E(name)}</button><small>${E(schema.type||'任意')} ${(s.inputSchema.required||[]).includes(name)?'· 必填':''}</small></td><td><div class="wf-modes" role="radiogroup" aria-label="${E(name)} 取值方式">${modes.map(([v,label])=>`<label><input type="radio" name="mode-${E(name)}" data-mode-field="${E(name)}" value="${v}" ${mode===v?'checked':''}>${label}</label>`).join('')}</div></td><td>${detail}<small>${mode==='output'?'固定來源 · 不回退預設':mode==='value'?'僅影響此節點；保留 JSON 型別':'不修改場景庫預設值'}</small></td></tr>`}).join('')}</tbody></table>`}</div><div class="wf-params-foot"><span id="wf-save-state" role="status"></span><button class="button" id="wf-reset-params">重設此節點</button><button class="button primary" id="wf-save-params">儲存參數</button></div>`;
    q('#wf-collapse').onclick=()=>{collapsed=!collapsed;parameters()};q('#wf-save-params').onclick=persist;q('#wf-reset-params').onclick=()=>{if(!n||busy)return;n.bindings={};delete raw[n.id];changed();parameters()};
    box.querySelectorAll('[data-mode-field]').forEach(r=>r.onchange=()=>{if(busy)return;const name=r.dataset.modeField;if(r.value==='auto')delete n.bindings[name];else if(r.value==='default')n.bindings[name]={kind:'default'};else if(r.value==='value'){const v=n.bindings[name]?.value??s.defaults[name]??'';n.bindings[name]={kind:'value',value:C(v)}}else n.bindings[name]={kind:'output',source:'',field:''};changed();parameters();if(r.value==='value')[...box.querySelectorAll('[data-manual]')].find(e=>e.dataset.manual===name)?.focus()});
    box.querySelectorAll('[data-manual]').forEach(i=>i.oninput=()=>{if(busy)return;(raw[n.id]??={})[i.dataset.manual]=i.value;changed()});
    box.querySelectorAll('[data-binding]').forEach(i=>i.onchange=()=>{const[source,field]=i.value.split('|');if(source)bindField(i.dataset.binding,source,field)});
    box.querySelectorAll('[data-input-port]').forEach(b=>b.onclick=()=>{if(picked?.field)bindField(b.dataset.inputPort,picked.node,picked.field);else toast('先點選右側的上游出參')});
    box.querySelectorAll('[data-field-row]').forEach(row=>{row.ondragover=e=>{e.preventDefault();row.classList.add('selected-field')};row.ondragleave=()=>row.classList.remove('selected-field');row.ondrop=e=>{e.preventDefault();row.classList.remove('selected-field');if(picked?.field)bindField(row.dataset.fieldRow,picked.node,picked.field)}});
    if(error){message=error;status(true)}else status();if(busy)box.querySelectorAll('input,select,button').forEach(e=>e.disabled=true);
  }
  function persist(){if(busy)return false;try{syncRaw();Parameters.prepare(draft,catalog());const disk=storeRead('automation-demo-v2',{});if((disk.workflowRevision||0)!==storageVersion)throw Error('工作流已在其他頁面變更，請匯出目前草稿後重載');const candidate={...state,workflow:C(draft),workflowRevision:storageVersion+1};if(!storeWrite('automation-demo-v2',candidate))throw Error('儲存失敗；輸入草稿已保留');state=candidate;storageVersion++;dirty=false;raw={};message='已儲存 · 工作流版本 '+storageVersion;status();return true}catch(e){message=e.message;status(true);return false}}
  function summary(){const box=q('#wf-result');if(!box)return;box.innerHTML=`<div><strong>${busy?'模擬執行中':last?.status||'等待執行'}</strong><span>${last?last.calls.length+' / '+last.total+' 次':'建立 ×2 → 驗證 ×1'}</span><progress max="${last?.total||3}" value="${last?.calls.length||0}"></progress><a href="#reports">查看場景報告</a><a href="sample-run/index.html">真實 Python 範例</a></div>${last?`<details><summary>展開本次參數與執行記錄</summary><pre>${E(JSON.stringify(last,null,2))}</pre></details>`:'<span class="wf-mini">先檢查固定值與來源；每個節點開始前再驗證實際入參。</span>'}`}
  function lock(){document.querySelectorAll('.wf-layout input,.wf-layout select,.wf-layout button,.wf-toolbar button').forEach(e=>e.disabled=busy);if(q('#wf-stop'))q('#wf-stop').disabled=!busy}
  async function run(){if(busy)return;if(!persist())return;let p;try{p=Parameters.prepare(draft,catalog())}catch(e){message=e.message;status(true);return}const failNode=q('#wf-fail')?.value;busy=true;stop=false;last={status:'執行中',total:p.total,calls:[],plans:p.plans};lock();summary();
    try{for(const id of p.order){const n=p.graph.nodes.find(n=>n.id===id);for(let i=1;i<=n.repeat;i++){if(stop)throw Error('使用者已停止；已完成步驟不回滾');const inputs=Parameters.resolve(p.catalog[n.sceneId],p.plans[id],last.calls);await new Promise(r=>setTimeout(r,130));if(stop)throw Error('使用者已停止；已完成步驟不回滾');const r=simulate(p.catalog[n.sceneId],inputs,id===failNode);r.workflow={nodeId:id,iteration:i,bindings:C(p.plans[id]),sources:Object.fromEntries(Object.entries(p.plans[id]).filter(([,b])=>b.kind==='output').map(([name,b])=>[name,[...last.calls].reverse().find(c=>c.nodeId===b.source).runId]))};save();last.calls.push({nodeId:id,iteration:i,runId:r.runId,status:r.status,inputs:C(inputs),outputs:C(r.output)});summary();if(r.status!=='passed')throw Error(r.error||'前置節點失敗')}}last.status='全部通過 · 離線模擬'}catch(e){last.status=stop?'已停止':'失敗';last.error=e.message}finally{busy=false;lock();parameters();summary()}}
  function mount(){init();graph();config();parameters();summary();
    document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{if(busy)return;const id='node-'+Date.now().toString(36);draft.nodes.push({id,sceneId:b.dataset.add,repeat:1,x:40+(draft.nodes.length%3)*230,y:190,bindings:{}});selected=id;changed();graph();config();parameters()});
    q('#wf-save').onclick=persist;q('#wf-run').onclick=run;q('#wf-stop').onclick=()=>{stop=true;q('#wf-stop').disabled=true};
    q('#wf-export').onclick=()=>{try{syncRaw();Parameters.prepare(draft,catalog());download('workflow.json',JSON.stringify(draft,null,2),'application/json')}catch(e){message=e.message;status(true)}};
    q('#wf-minus').onclick=()=>{zoom=Math.max(.35,zoom-.1);scale()};q('#wf-plus').onclick=()=>{zoom=Math.min(1.8,zoom+.1);scale()};q('#wf-fit').onclick=()=>{const right=Math.max(260,...draft.nodes.map(n=>n.x+220)),bottom=Math.max(150,...draft.nodes.map(n=>n.y+115)),v=q('.wf-viewport');zoom=Math.min(1,v.clientWidth/right,v.clientHeight/bottom);scale();v.scrollTo(0,0)};
    lock();
  }
  window.addEventListener('resize',edges);window.addEventListener('keydown',e=>{if(e.key==='Escape'&&q('#wf-parameters')){collapsed=true;parameters()}});
  return {html,mount,initial,reset:()=>{draft=null;raw={};dirty=false;last=null;selected='verify'},snapshot:()=>({draft:C(draft),dirty,zoom,raw:C(raw),last:C(last),busy})};
})();
